import React, { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import axios from "axios";

const UserViewProfile = () => {
  const { id } = useParams();
  const [user, setUser] = useState(null);
  const [profile, setProfile] = useState(null);
  const navigate = useNavigate();

  useEffect(() => {
    const fetchProfile = async () => {
      try {
        const res = await axios.get(`http://localhost:5000/api/profile/${id}`);
        setUser(res.data.user);
        setProfile(res.data.profile);
      } catch (err) {
        console.error("Error fetching user profile:", err);
      }
    };
    fetchProfile();
  }, [id]);

  return (
    <div className="profile-container">
      <h2 className="profile-title">User Profile</h2>

      {user ? (
        <>
          <p><b>Username:</b> {user.username}</p>
          <p><b>Email:</b> {user.email}</p>
        </>
      ) : (
        <p>No user data.</p>
      )}

      {profile ? (
        <>
          <p><b>Bio:</b> {profile.bio}</p>
          <p><b>Genres:</b> {profile.genres.join(", ")}</p>
          <p><b>Instruments:</b> {profile.instruments.join(", ")}</p>
          <p><b>Years of Experience:</b> {profile.yearsOfExperience}</p>
          <p><b>City:</b> {profile.city}</p>
          <p><b>YouTube:</b> <a href={profile.youtube} target="_blank" rel="noreferrer">Link</a></p>
          <p><b>Instagram:</b> <a href={profile.instagram} target="_blank" rel="noreferrer">Link</a></p>
        </>
      ) : (
        <p>No profile data.</p>
      )}

      <button className="back-btn" onClick={() => navigate(-1)}>⬅️ Back</button>
    </div>
  );
};

export default UserViewProfile;
